function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ($http>=200&&$http<300&&is_array($d))?$d:[];}
$events=sbq('goliath_events?select=*&or=(department.eq.Columbo,metadata.cs.'.rawurlencode(json_encode(['cycle'=>'archive_gold_mining'])).')&order=created_at.desc&limit=80');
$tasks=sbq('local_ai_tasks?select=*&or=(metadata.cs.'.rawurlencode(json_encode(['agent'=>'Columbo'])).',task_type.ilike.*columbo*)&order=created_at.desc&limit=60');
$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Columbo Archive Vault</title><link rel="stylesheet" href="/dashboard/assets/goliath-v33.css?v=33"><link rel="stylesheet" href="/dashboard/assets/goliath-v45-final.css?v=458"><style>.vaultHero{border-radius:24px;padding:24px;background:linear-gradient(135deg,#17120d,#2b2117);border:1px solid rgba(255,255,255,.12);box-shadow:0 20px 70px rgba(0,0,0,.35);margin:18px 0}.vaultHero h2{font-size:34px;margin:6px 0}.vaultGrid{display:grid;grid-template-columns:1fr 390px;gap:18px}.goldCard{padding:14px;border:1px solid rgba(255,255,255,.1);border-radius:16px;background:rgba(255,255,255,.04);margin-bottom:10px}.input{width:100%;padding:12px;border-radius:12px;border:1px solid rgba(255,255,255,.14);background:#0d1117;color:#fff;margin:6px 0}@media(max-width:980px){.vaultGrid{grid-template-columns:1fr}.vaultHero h2{font-size:26px}}</style></head><body><div class="shell"><?php require __DIR__.'/includes/goliath-sidebar-v33.php'; ?><main class="main"><section class="top"><div><h1>🕵️‍♂️ Columbo Archive Vault</h1><p>Columbo’s only job: find lost gold inside Mark’s long-form archive and send the winners to Scorsese.</p></div><div class="brandbar"><a class="btn dark" href="/dashboard/goliath-mission-control.php">Mission Control</a><a class="btn" href="/dashboard/goliath-agent-detail.php?department=Columbo">Columbo Office</a></div></section><section class="vaultHero"><span class="serialBadge">Content Archaeologist</span><h2>Recover the songs, comedy, emotional moments and hidden shorts nobody saw.</h2><p>Queue channel scans, paste single episode URLs, watch Columbo score moments, then send Scorsese timestamped cut briefs for shorts.</p><button class="btn" onclick="seedArchive()">Start Archive Hunt</button></section><section class="vaultGrid"><section class="panel"><h2>Gold-Mining Activity <span><?=count($events)?> events</span></h2><div class="inner"><?php if(!$events):?><p>No archive events yet. Start Archive Hunt to queue Columbo.</p><?php endif;?><?php foreach($events as $e):?><div class="goldCard"><strong><?=h($e['title']??'Columbo archive activity')?></strong><br><small><?=h(!empty($e['created_at'])?date('M j g:i A',strtotime($e['created_at'])):'')?> · Status: <?=h($e['status']??'queued')?> · Confidence <?=h($e['confidence']??90)?>%</small><p><?=h($e['detail']??'')?></p></div><?php endforeach;?></div></section><aside class="panel"><h2>Manual Episode Scan</h2><div class="inner"><input class="input" id="episodeTitle" placeholder="Episode title / note"><input class="input" id="episodeUrl" placeholder="YouTube episode URL"><button class="btn" onclick="scanEpisode()">Queue Episode Scan</button><div id="vaultResult" style="margin-top:12px"></div></div><h2>Columbo Queue <span><?=count($tasks)?></span></h2><div class="inner"><?php foreach($tasks as $t):?><p><strong><?=h($t['status']??'queued')?></strong> — <?=h(mb_strimwidth($t['prompt']??'',0,150,'...'))?></p><?php endforeach;?></div></aside></section></main></div><script>
const KEY=<?=json_encode($key)?>;
async function postArchive(payload){const box=document.getElementById('vaultResult');box.innerHTML='Queuing Columbo...';try{const r=await fetch('/lead-engine/goliath-columbo-archive.php?key='+encodeURIComponent(KEY),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();box.innerHTML=j.success?'✅ '+j.message+' Tasks: '+j.tasks_queued:'⚠️ '+(j.error||'Queue failed');}catch(e){box.innerHTML='⚠️ Could not reach Columbo archive endpoint.'}}
function seedArchive(){postArchive({action:'seed_archive',limit:12});}
function scanEpisode(){const url=document.getElementById('episodeUrl').value.trim();const title=document.getElementById('episodeTitle').value.trim()||'Manual episode';if(!url){document.getElementById('vaultResult').innerHTML='Paste a YouTube episode URL first.';return;}postArchive({action:'scan_episode',url,title});}
</script></body></html>
